Definition KOBLITZ_STACK : Z := 512.

Definition koblitz_xl (bits : Z) : Z := bits / 16.

Definition koblitz_rtabB (segs : list Segment) (R : art_layout) (HIA : artA segs R) (RP : Z) (rs : list word) : Prop :=
  length rs = 2%nat /\ 0 < RP /\ RP mod 4 = 0 /\
  hl_img_lo (arl_L R) <= RP /\ RP + 8 <= hl_img_hi (arl_L R) /\
  (forall (h : HST segs R HIA) (LB LF : list blk) (m : mem), HM segs R HIA h LB LF m ->
     bytes_at segs m RP (u32s rs) /\ aobj segs (arl_AL R) (hcs segs R HIA h) m RP 8).

Definition koblitz_postB (segs : list Segment) (R : art_layout) (HIA : artA segs R)
    (h : HST segs R HIA) (LB LF : list blk)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (X XL lo : Z) (xs : list word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem) (h' : HST segs R HIA) (xs' : list word),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom segs)
    /\ u32arr segs m' X xs' /\ length xs' = length xs
    /\ hcs segs R HIA h' = hcs segs R HIA h /\ htop segs R HIA h' = htop segs R HIA h
    /\ hstkhi segs R HIA h' = hstkhi segs R HIA h /\ hflag segs R HIA h' = hflag segs R HIA h
    /\ havol segs R HIA h' = havol segs R HIA h /\ hfr segs R HIA h' = hfr segs R HIA h
    /\ (forall mo : Model, HK segs R HIA h' mo <-> HK segs R HIA h mo)
    /\ HM segs R HIA h' LB LF m'
    /\ presW segs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * XL)] m m'
    /\ mem_inv segs m' /\ stk segs m' lo (bv_unsigned sp).

Definition koblitz_stmtB (segs : list Segment) (R : art_layout) (HIA : artA segs R) (ENTRY : Z) : Prop :=
  forall (h : HST segs R HIA) (LB LF : list blk)
         (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem)
         (X XB RP bits lo : Z) (xs rs : list word),
  HM segs R HIA h LB LF m ->
  (length LF + 1 <= 512)%nat ->
  bits = 192 \/ bits = 224 \/ bits = 256 ->
  u32arr segs m X xs ->
  koblitz_xl bits <= Z.of_nat (length xs) ->
  In (X, XB) LB -> 4 * Z.of_nat (length xs) <= XB -> X mod 4 = 0 ->
  koblitz_rtabB segs R HIA RP rs -> RP + 8 <= lo ->
  stk segs m lo (bv_unsigned sp) -> arl_stklo R <= lo ->
  lo <= bv_unsigned sp - KOBLITZ_STACK - arl_need_ecp R ->
  bv_unsigned sp <= htop segs R HIA h -> bv_unsigned sp mod 16 = 0 ->
  tp = Z_to_bv 64 (arl_tp R) -> mem_inv segs m -> bv_unsigned ra mod 2 = 0 ->
  a0 = Z_to_bv 64 X -> a1 = Z_to_bv 64 RP -> a2 = Z_to_bv 64 bits ->
  evtA segs (arl_AL R) (hcs segs R HIA h)
    (koblitz_postB segs R HIA h LB LF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc X (koblitz_xl bits) lo xs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 ENTRY) fc None m (seg_rom segs)).

Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Local Ltac pqlia ::= ff5_pqlia.
Local Ltac transport_after_call segs m m' MU WM ::= ff5_transport_after_call segs m m' MU WM.
Local Ltac solve_apart ::= ff5_solve_apart.
Local Ltac solve_apart0 ::= ff5_solve_apart0.
Local Ltac solve_disjoint ::= ff5_solve_disjoint.

Ltac pctx := try (match goal with H : ?T |- _ => idtac "HYP" H ":" T; fail end); match goal with |- ?g => idtac "GOAL:" g end.

Lemma u32arr_of_u8arr_u32s : forall segs m A ws, u8arr segs m A (u32s ws) -> u32arr segs m A ws.
Proof.
  intros segs m A ws [Hb Hw]. split; [exact Hb|]. rewrite u32s_length in Hw.
  replace (4 * Z.of_nat (length ws)) with (Z.of_nat (4 * length ws)) by lia. exact Hw.
Qed.

Lemma u8arr_app_l : forall segs m A l1 l2, u8arr segs m A (l1 ++ l2) -> u8arr segs m A l1.
Proof.
  intros segs m A l1 l2 [Hb Hw]. apply bytes_at_app in Hb. destruct Hb as [Hb1 _].
  rewrite app_length, Nat2Z.inj_add in Hw. apply wr_at_app in Hw; [| lia | lia]. destruct Hw as [Hw1 _].
  split; assumption.
Qed.

Lemma u8arr_zero_prefix : forall segs m A (n k : nat), (k <= n)%nat ->
  u8arr segs m A (repeat (Z_to_bv 8 0) n) -> u8arr segs m A (repeat (Z_to_bv 8 0) k).
Proof.
  intros segs m A n k Hk H. replace n with (k + (n - k))%nat in H by lia. rewrite repeat_app in H.
  eapply u8arr_app_l; exact H.
Qed.

Lemma u32arr_mid : forall segs m A ws (k j : nat), (k + j <= length ws)%nat -> u32arr segs m A ws ->
  u32arr segs m (A + 4 * Z.of_nat k) (firstn j (skipn k ws)) /\ length (firstn j (skipn k ws)) = j.
Proof.
  intros segs m A ws k j Hl H. rewrite <- (firstn_skipn k ws) in H. apply u32arr_app in H. destruct H as [_ H2].
  rewrite firstn_length_le in H2 by lia. rewrite <- (firstn_skipn j (skipn k ws)) in H2. apply u32arr_app in H2.
  destruct H2 as [H3 _]. split; [exact H3|]. rewrite firstn_length_le; [reflexivity|]. rewrite skipn_length. lia.
Qed.

Definition kob_meta (v : Z) : list cell :=
  repeat (C1 (Z_to_bv 8 241)) 4%nat ++ repeat (C1 (Z_to_bv 8 0)) 4%nat ++ repeat (C1 (Z_to_bv 8 242)) 4%nat ++
  repeat (C1 (Z_to_bv 8 v)) 5%nat ++ repeat (C1 (Z_to_bv 8 243)) 7%nat ++ repeat (C1 (Z_to_bv 8 0)) 8%nat.

Section KW.
  Variable R : art_layout.
  Variable HIA : artA asegs R.
  Local Notation AL := (arl_AL R).
  Local Notation L := (arl_L R).
  Hypothesis IMG : asan_img_ok AL.
  Hypothesis UARG : arl_uar_got R = A_UAR_GOT_KB.
  Hypothesis SM2 : arl_smalloc R 2 = A_SMALLOC_2_KB.
  Hypothesis NS1 : 0 <= arl_need_smalloc R.
  Hypothesis NEEDR : 0 <= arl_need_rt R.
  Hypothesis AMS : arl_amemset R = A_ASAN_MEMSET_KB.
  Hypothesis AMC : arl_amemcpy R = A_ASAN_MEMCPY_KB.
  Hypothesis CMUL : mpi_core_mul_stmtA asegs R HIA A_MPI_CORE_MUL.
  Hypothesis CADD : mpi_core_add_stmtA asegs (arl_AL R) A_MPI_CORE_ADD.

  Variables (h : HST asegs R HIA) (LB LF : list blk).
  Local Notation CS := (hcs asegs R HIA h).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (X XB RP lo : Z) (xs rs : list word).
  Hypothesis LFB : (length LF + 1 <= 512)%nat.
  Hypothesis XIN : In (X, XB) LB.
  Hypothesis XBL : 4 * Z.of_nat (length xs) <= XB.
  Hypothesis XAL : X mod 4 = 0.
  Hypothesis RT : koblitz_rtabB asegs R HIA RP rs.
  Hypothesis RPL : RP + 8 <= lo.
  Hypothesis LOS : arl_stklo R <= lo.
  Hypothesis SLO : lo <= bv_unsigned sp - KOBLITZ_STACK - arl_need_ecp R.
  Hypothesis TOP : bv_unsigned sp <= htop asegs R HIA h.
  Hypothesis SPA : bv_unsigned sp mod 16 = 0.
  Hypothesis TPV : tp = Z_to_bv 64 (arl_tp R).
  Hypothesis RAE : bv_unsigned ra mod 2 = 0.

  Local Notation Q P := (koblitz_postB asegs R HIA h LB LF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc X (2 * P) lo xs m).

  Ltac rt_facts :=
    pose proof (hcs_ok asegs R HIA h) as CSOK;
    pose proof (cs_ok_sb _ _ CSOK) as SB64;
    pose proof (art_alwf asegs R HIA) as ALWF'; unfold al_wf in ALWF';
    pose proof IMG as IMG'; unfold asan_img_ok in IMG';
    pose proof (art_uar_img asegs R HIA) as UIMG;
    pose proof (art_lo asegs R HIA) as ALO;
    pose proof (alloc_ceiling_pos (L := arl_L R)) as ACP; pose proof (alloc_ceiling_val R) as ACV;
    unfold A_UAR_GOT_KB in UARG; unfold A_SMALLOC_2_KB in SM2; unfold KOBLITZ_STACK in SLO;
    pose proof (hcs_stack asegs R HIA h) as SCS0;
    pose proof (arl_need_ecp_rt R) as NER; pose proof (arl_need_ecp_smalloc R) as NES;
    pose proof (arl_need_rt_amem R) as NRA;
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; cbn [Z.pow Z.of_N Pos.pow] in SPR.

  Lemma x_facts : forall h' LB' LF' m', HM asegs R HIA h' LB' LF' m' -> In (X, XB) LB' ->
    0 < X /\ X + XB <= alloc_ceiling (L := arl_L R).
  Proof.
    intros h' LB' LF' m' HH' HI. destruct (hm_apart asegs R HIA _ _ _ _ HH') as [HB _]. rewrite Forall_forall in HB.
    destruct (HB (X, XB) ltac:(apply in_app_iff; left; exact HI)) as (A1 & A2 & A3 & A4). cbn [fst snd] in *. lia.
  Qed.

  Lemma x_presA : forall LB' LF' SP SSP TP W m1 m2 ws,
    presA asegs R LB' LF' SP SSP TP W m1 m2 -> u32arr asegs m1 X ws -> In (X, XB) LB' ->
    4 * Z.of_nat (length ws) <= XB -> disjoint_from W X (4 * Z.of_nat (length ws)) -> u32arr asegs m2 X ws.
  Proof.
    intros LB' LF' SP SSP TP W m1 m2 ws HP HA HI HL HD. apply u32arr_of_u8arr_u32s.
    eapply (presA_u8arr asegs R); [exact HP | apply u8arr_of_u32arr; exact HA | |].
    - eapply client_range_block; [apply in_or_app; left; exact HI | lia | rewrite u32s_length; lia].
    - rewrite u32s_length. replace (Z.of_nat (4 * length ws)) with (4 * Z.of_nat (length ws)) by lia. exact HD.
  Qed.

  Ltac carryX :=
    match goal with
    | XA0 : u32arr asegs ?m0 X ?l, MU : munch ?W ?m0 ?mx, WM : wmono asegs ?m0 ?mx |- evtA _ _ _ _ (MS _ _ _ _ _ ?mx _) =>
        let D := fresh "XD" in
        assert (D : disjoint_from W X (4 * Z.of_nat (length l)));
        [ first [ solve_disjoint | match goal with |- ?g => idtac "XD-LEFT" g end; fail ] | ];
        let XN := fresh "XN" in
        pose proof (u32arr_transport asegs _ m0 mx X l XA0 MU WM D) as XN; clear XA0 D; rename XN into XA
    end.

  Ltac dropmem mm := repeat match goal with H : context [mm] |- _ => clear H end; try clear mm.
  Ltac curmem := match goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) => mc end.
  Ltac rn_frame FB :=
    let mx := curmem in
    try (match goal with H : rw_cells _ mx (Z.shiftr FB 3 + al_sb _) _ |- _ => rename H into FSH end);
    try (match goal with H : rw_cells _ mx (FB + 32) _ |- _ => rename H into MPB end);
    try (match goal with H : rw_cells _ mx (FB + 96) _ |- _ => rename H into RPB end);
    try (match goal with H : rw_cells _ mx FB _ |- _ => rename H into FHD end).
  Ltac klia := clear_disj; lia.
  Ltac rw_hcs := match goal with E : hcs asegs R HIA _ = hcs asegs R HIA h |- _ => rewrite E end.
  Ltac rw_htop := match goal with E : htop asegs R HIA _ = htop asegs R HIA h |- _ => rewrite E end.
  Ltac amem_ob :=
    first [ left; first [ rewrite AMS | rewrite AMC ]; reflexivity
          | reflexivity
          | eassumption
          | rw_hcs; eassumption
          | match goal with E : length ?l = _ |- Z.of_nat (length ?l) = _ => rewrite E; reflexivity end
          | lazymatch goal with |- crange _ _ _ =>
              rw_hcs; eapply crange_sub; [match goal with S : crange _ lo (bv_unsigned sp - lo) |- _ => exact S end | klia | klia] end
          | lazymatch goal with |- client_wrange _ _ _ _ ?A _ =>
              match goal with I : In (?B, ?k) _ |- _ => eapply (client_wrange_block _ _ _ _ A _ B k I); klia end end
          | lazymatch goal with |- _ <= htop _ _ _ _ => rw_htop; klia end
          | left; klia | right; klia | klia
          | match goal with |- ?g => idtac "AMEM-LEFT" g end ].

  Local Notation KSAVES := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Definition kob_fbok (FB : Z) : Prop :=
    fresh_apart R LB LF FB 256 /\ FB mod 64 = 0 /\ FB mod 8 = 0 /\ 0 < FB /\ FB + 256 <= lo /\
    crange CS FB 256 /\
    In (FB, 24) (LB ++ fdata ((FB, 256) :: LF)) /\ In (FB + 32, 216) (LB ++ fdata ((FB, 256) :: LF)) /\
    (forall B j : Z, In (B, j) LF -> FB + 256 <= B \/ B + j <= FB) /\
    (forall B j : Z, In (B, j) (LB ++ fdata LF) -> FB + 256 <= B \/ B + j <= FB) /\
    FB + 256 <= alloc_ceiling (L := arl_L R) /\
    (FB + 256 <= hl_data_lo L \/ hl_data_hi L <= FB) /\
    (hl_data_hi L <= Z.shiftr FB 3 + al_sb AL /\ Z.shiftr FB 3 + al_sb AL + 32 <= alloc_ceiling (L := arl_L R)) /\
    (Z.shiftr FB 3 + al_sb AL + 32 <= FB \/ FB + 256 <= Z.shiftr FB 3 + al_sb AL) /\
    (FB + 256 <= X \/ X + XB <= FB) /\
    (X + XB <= Z.shiftr FB 3 + al_sb AL \/ Z.shiftr FB 3 + al_sb AL + 32 <= X).

  Definition kob_sp2ok (sp2 : Z) : Prop :=
    sp2 mod 32 = 0 /\ bv_unsigned sp - 272 <= sp2 <= bv_unsigned sp - 256.

  Definition kob_hrel (h1 : HST asegs R HIA) : Prop :=
    hcs asegs R HIA h1 = CS /\ htop asegs R HIA h1 = htop asegs R HIA h /\
    hstkhi asegs R HIA h1 = hstkhi asegs R HIA h /\ hflag asegs R HIA h1 = hflag asegs R HIA h /\
    havol asegs R HIA h1 = havol asegs R HIA h /\ hfr asegs R HIA h1 = hfr asegs R HIA h /\
    (forall mo : Model, HK asegs R HIA h1 mo <-> HK asegs R HIA h mo).

  Definition kob_rfr (P FB sp2 : Z) (m1 : mem) : Prop :=
    stk asegs m1 lo sp2 /\ stk asegs m1 sp2 (sp2 + 24) /\
    rw_cells asegs m1 (sp2 + 24) [C8 (Z_to_bv 64 FB); C8 (Z_to_bv 64 FB)] /\
    stk asegs m1 (sp2 + 40) (sp2 + 72) /\
    rw_cells asegs m1 (sp2 + 72)
      [C8 (Z_to_bv 64 (X + 4 * P)); C8 (Z_to_bv 64 (X + 4 * P)); C8 (Z_to_bv 64 (P + 2)); C8 (Z_to_bv 64 RP);
       C8 (Z_to_bv 64 X); C8 (Z_to_bv 64 (FB + 96)); C8 (Z_to_bv 64 0)] /\
    stk asegs m1 (sp2 + 128) (bv_unsigned sp - 104) /\
    rw_cells asegs m1 (bv_unsigned sp - 104) KSAVES.

  Lemma kob_epi : forall (P : Z), 6 <= P <= 8 -> 2 * P <= Z.of_nat (length xs) ->
    forall (h1 : HST asegs R HIA) (FB sp2 : Z) (m1 : mem) (xs1 : list word) (w0 w1 w2 : word)
           (ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v2 v3 v4 v5 v6 v7 v9 v10 t3 t4 t5 t6 : word),
    HM asegs R HIA h1 LB ((FB, 256) :: LF) m1 -> kob_hrel h1 -> kob_fbok FB -> kob_sp2ok sp2 ->
    mem_inv asegs m1 ->
    presW asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] m m1 ->
    u32arr asegs m1 X xs1 -> length xs1 = length xs ->
    rw_cells asegs m1 (Z.shiftr FB 3 + al_sb AL) (kob_meta 0) ->
    rw_cells asegs m1 FB [C8 w0; C8 w1; C8 w2] ->
    kob_rfr P FB sp2 m1 ->
    evtA asegs AL CS (Q P)
      (MS (mkR ra1 (Z_to_bv 64 sp2) gp tp t0 t1 t2 sp (Z_to_bv 64 sp2) a0 a1 a2 a3 a4 a5 a6 a7
               v2 v3 v4 v5 v6 v7 (Z_to_bv 64 FB) v9 v10 (Z_to_bv 64 (Z.shiftr FB 3 + al_sb AL)) t3 t4 t5 t6)
          F (Z_to_bv 64 0xd7604) fc None m1 (seg_rom asegs)).
  Proof.
    intros P PR XLEN h1 FB sp2 m1 xs1 w0 w1 w2 ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v2 v3 v4 v5 v6 v7 v9 v10 t3 t4 t5 t6
           HH1 HR FOK S2OK MI PRES XA XL FSH FHD RFR.
    rt_facts.
    destruct HR as (Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI).
    destruct FOK as (FRSH & F64 & F8 & FB0 & FBLO & CFB & INH & IND & APL & APLB & FBCE & FBDL & SBND & APS & XFB & XM).
    destruct S2OK as (SP2M & SP2).
    destruct RFR as (ST1 & ST2 & LOC1 & ST3 & LOC2 & ST4 & SAVES).
    destruct (x_facts _ _ _ _ HH1 XIN) as [X0 XCE].
    pose proof (hm_top asegs R HIA h1 _ _ _ HH1) as HTOP1. rewrite ?Ehtop, ?Estk in HTOP1.
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| qlia| qlia]).
    assert (SP2R : 0 <= sp2 < 2^64) by (clear - SP2 SPR SLO LOS ALO ACV NEEDR NER; lia).
    assert (XBL1 : 4 * Z.of_nat (length xs1) <= XB) by (rewrite XL; exact XBL).
    pose proof (hm_wlow asegs R HIA h1 _ _ _ HH1) as WL1.
    pose proof (art_stk_high asegs R HIA) as STKH.
    assert (SFF : shadow_free R LB LF (arl_stklo R) (hstkhi asegs R HIA h) FB 256)
      by (eapply shadow_free_fresh; [exact FRSH | exact (proj2 (proj2 (proj2 PRES))) | clear; lia | clear; lia | exact ALO | exact APL]).
    unfold kob_meta in FSH. cbn [repeat app] in FSH.
    pose (lxi := lxA_img (arl_AL R) IMG).
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [0xd76c4] [] 80%N). lx_tree.
    all: try carryX.
    all: lxr_leaf; lxe_leaf_gc.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mx _) => rename mx into me end.
    match goal with H : HM _ _ _ h1 _ _ me |- _ => rename H into HHe end.
    destruct (hm_fake_free asegs R HIA h1 LB ((FB, 256) :: LF) me FB 256 HHe ltac:(left; reflexivity))
      as (p & h4 & ROp & [old Hold] & CRp & NCp & NSp & HM4 & E4cs & E4top & E4stk & E4flag & E4vol & E4fr & HKI4).
    replace (FB + 256 - 8) with (FB + 248) in ROp by (clear; lia).
    pose proof (rw_cells_bound _ _ _ _ Hold) as PB. cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in PB.
    pose proof (store_ok_of_rw1 _ _ _ _ Hold) as HSp. clear Hold.
    rewrite Ehcs in CRp.
    assert (ELF : lb_remove FB ((FB, 256) :: LF) = LF) by (cbn [lb_remove fst]; rewrite Z.eqb_refl; reflexivity).
    rewrite ELF in HM4. clear ELF.
    assert (NPS : bv_unsigned sp - 104 + 104 <= p \/ p + 1 <= bv_unsigned sp - 104).
    { eapply (nc_apart _ _ _ (arl_stklo R) _ p); [exact NCp| apply client_range_stack; clear - SLO LOS NEEDR NER; lia| intros b' Hb; exact Hb| clear; lia| clear; lia]. }
    assert (NX : X + 4 * Z.of_nat (length xs1) <= p \/ p + 1 <= X).
    { eapply (nc_apart _ _ _ (arl_stklo R) _ p);
        [exact NCp| eapply client_range_block; [apply in_or_app; left; exact XIN| clear; lia| clear - XBL1; lia]
        | intros b' Hb; exact Hb| clear; lia| clear - XL XLEN PR; lia]. }
    lazymatch goal with HP : presW _ _ _ _ _ _ ?SPx ?SSPx ?Wx _ me |- _ =>
      assert (WCp : wcover R LB LF SPx Wx p 1)
        by (eapply wcover_nc; [exact NCp | intros b' Hb; apply fdata_cons_sub; exact Hb | clear - LOS SLO NEEDR NER; lia]) end.
    assert (STKA : stk asegs me lo (bv_unsigned sp - 104)) by lx_stk_glue_top.
    clear HHe NCp NSp.
    zstep. zstep.
    clear ROp.
    lazymatch goal with |- _ (MS _ _ _ _ _ (write_to_mem ?mm ?a ?bs) _) =>
      change (write_to_mem mm a bs) with (write_to_mem mm (wa p) [Z_to_bv 8 0]) end.
    apply (stk_write asegs me lo (bv_unsigned sp - 104) p [Z_to_bv 8 0]) in STKA;
      [| clear - PB; lia | change (Z.of_nat (length [Z_to_bv 8 0])) with 1; clear - PB; lia].
    fake_free_done p HSp.
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [] [] 40%N). lx_tree.
    all: try carryX.
    all: lxr_leaf; lxe_leaf_gc.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mx _) => rename mx into mf end.
    apply evtA_done. unfold koblitz_postB.
    do 15 eexists. exists mf, h4, xs1.
    split; [reflexivity|].
    split; [eassumption|]. split; [exact XL|].
    split; [rewrite E4cs; exact Ehcs|]. split; [rewrite E4top; exact Ehtop|]. split; [rewrite E4stk; exact Estk|].
    split; [rewrite E4flag; exact Eflag|]. split; [rewrite E4vol; exact Evol|]. split; [rewrite E4fr; exact Efr|].
    split; [intros mo; split; intro K;
            [apply (proj1 (HKI mo)); apply (proj1 (HKI4 mo)); exact K | apply (proj2 (HKI4 mo)); apply (proj2 (HKI mo)); exact K]|].
    split; [eassumption|]. split; [eassumption|]. split; [eassumption|].
    lx_stk_glue_top.
  Qed.

  Lemma k3_split3 : forall segs mm A ws (k : nat), (2 * k <= length ws)%nat -> u32arr segs mm A ws ->
    u32arr segs mm A (firstn k ws) /\ u32arr segs mm (A + 4 * Z.of_nat k) (firstn k (skipn k ws)) /\
    u32arr segs mm (A + 4 * Z.of_nat (2 * k)) (skipn (2 * k) ws).
  Proof.
    intros segs mm A ws k Hl H.
    assert (E : ws = firstn k ws ++ firstn k (skipn k ws) ++ skipn (2 * k) ws).
    { rewrite <- (firstn_skipn k ws) at 1. f_equal. rewrite <- (firstn_skipn k (skipn k ws)) at 1. f_equal.
      rewrite skipn_skipn. f_equal. lia. }
    assert (L1 : length (firstn k ws) = k) by (apply firstn_length_le; lia).
    assert (L2 : length (firstn k (skipn k ws)) = k) by (apply firstn_length_le; rewrite skipn_length; lia).
    rewrite E in H. apply u32arr_app in H. destruct H as [H1 H23]. apply u32arr_app in H23. destruct H23 as [H2 H3].
    rewrite L1 in H2, H3. rewrite L2 in H3.
    split; [exact H1|]. split; [exact H2|].
    replace (A + 4 * Z.of_nat (2 * k)) with (A + 4 * Z.of_nat k + 4 * Z.of_nat k) by lia. exact H3.
  Qed.

  Lemma k3_join3 : forall segs mm A l1 l2 l3, u32arr segs mm A l1 ->
    u32arr segs mm (A + 4 * Z.of_nat (length l1)) l2 ->
    u32arr segs mm (A + 4 * Z.of_nat (length l1) + 4 * Z.of_nat (length l2)) l3 ->
    u32arr segs mm A (l1 ++ l2 ++ l3).
  Proof.
    intros segs mm A l1 l2 l3 H1 H2 H3. apply u32arr_app. split; [exact H1|]. apply u32arr_app. split; [exact H2|exact H3].
  Qed.

  Lemma k3_zeros : forall segs mm A (k : nat), u8arr segs mm A (repeat (Z_to_bv 8 0) (4 * k)) ->
    u32arr segs mm A (repeat (Z_to_bv 64 0) k).
  Proof. intros segs mm A k H. rewrite <- u32s_repeat0 in H. apply u32arr_of_u8arr_u32s. exact H. Qed.

  Ltac k3_aobj :=
    lazymatch goal with |- aobj _ _ _ _ _ _ =>
      first [ match goal with O : aobj _ _ _ _ _ _ |- _ => eapply aobj_sub; [exact O | klia | klia] end
            | rw_hcs; match goal with O : aobj _ _ _ _ _ _ |- _ => eapply aobj_sub; [exact O | klia | klia] end ] end.
  Ltac k3_disj :=
    lazymatch goal with |- _ \/ _ =>
      match goal with D : _ \/ _ |- _ =>
        destruct D as [FI|FI]; [first [left; klia | right; klia] | first [left; klia | right; klia]] end end.
  Ltac k3_ob :=
    try unfold MPI_CORE_MUL_STACK_A, MPI_CORE_ADD_STACK_A;
    first [ left; rewrite AMS; reflexivity
          | reflexivity
          | eassumption
          | exact (art_alwf asegs R HIA)
          | left; split; reflexivity
          | lazymatch goal with |- Z.of_nat (length (u32s _)) = _ => rewrite u32s_length; klia end
          | lazymatch goal with |- crange _ _ _ =>
              try rw_hcs; eapply crange_sub; [match goal with S : crange _ lo (bv_unsigned sp - lo) |- _ => exact S end | klia | klia] end
          | lazymatch goal with |- client_wrange _ _ _ _ ?A _ =>
              match goal with I : In (?B, ?k) _ |- _ => eapply (client_wrange_block _ _ _ _ A _ B k I); klia end end
          | k3_aobj
          | lazymatch goal with |- _ <= htop _ _ _ _ => rw_htop; klia end
          | left; klia | right; klia | klia
          | k3_disj ].

  Lemma kob_pass3 : forall (P : Z), 6 <= P <= 8 -> 2 * P <= Z.of_nat (length xs) ->
    forall (h1 : HST asegs R HIA) (FB sp2 : Z) (m1 : mem) (xs1 a1s a0s : list word) (w0 w1 w2 : word)
           (ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v3 v10 t3 t4 t5 t6 : word),
    HM asegs R HIA h1 LB ((FB, 256) :: LF) m1 -> kob_hrel h1 -> kob_fbok FB -> kob_sp2ok sp2 ->
    mem_inv asegs m1 ->
    presW asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] m m1 ->
    u32arr asegs m1 X xs1 -> length xs1 = length xs ->
    rw_cells asegs m1 (Z.shiftr FB 3 + al_sb AL) (kob_meta 0) ->
    rw_cells asegs m1 FB [C8 w0; C8 w1; C8 w2] ->
    u32arr asegs m1 (FB + 32) a1s -> length a1s = Z.to_nat P ->
    u32arr asegs m1 (FB + 96) a0s -> length a0s = Z.to_nat (P + 2) ->
    kob_rfr P FB sp2 m1 ->
    evtA asegs AL CS (Q P)
      (MS (mkR ra1 (Z_to_bv 64 sp2) gp tp t0 t1 t2 sp (Z_to_bv 64 sp2) a0 a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 (FB + 32)) v3 (Z_to_bv 64 (X + 4 * P)) (Z_to_bv 64 RP) (Z_to_bv 64 X) (Z_to_bv 64 P)
               (Z_to_bv 64 FB) (Z_to_bv 64 (4 * P)) v10 (Z_to_bv 64 (Z.shiftr FB 3 + al_sb AL)) t3 t4 t5 t6)
          F (Z_to_bv 64 0xd75c4) fc None m1 (seg_rom asegs)).
  Proof.
    intros P PR XLEN h1 FB sp2 m1 xs1 a1s a0s w0 w1 w2 ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v3 v10 t3 t4 t5 t6
           HH HREL FBOK SP2OK MI PRES XA XL1 FSH FHD MPA LA1 RPA LA0 RFR.
    rt_facts.
    pose proof HREL as HREL'. destruct HREL' as (Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI).
    pose proof FBOK as FBOK'.
    destruct FBOK' as (FRSH & F64 & F8 & FB0 & FBLO & CFB & INH & IND & LFA & LBA & FBAC & FBD & SBND & APS & XFB & XM).
    destruct SBND as [SBND1 SBND2].
    pose proof SP2OK as SP2OK'. destruct SP2OK' as (SP2M & SP2).
    destruct RFR as (ST1 & SK1 & RFA & SK2 & RFL & SK3 & SVS).
    destruct (x_facts _ _ _ _ HH XIN) as [X0 XCE].
    pose proof (alloc_ceiling_top47 (L := arl_L R)) as AC47.
    pose proof (hm_top asegs R HIA _ _ _ _ HH) as HTOP.
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| klia| klia]).
    assert (SP2R : 0 <= sp2 < 2^64) by (clear - SP2 SPR SLO LOS ALO ACV NEEDR NER; lia).
    pose proof RT as RT'. destruct RT' as (LRS & RP0 & RPA4 & RPLO & RPHI & RTM).
    destruct (hm_apart asegs R HIA _ _ _ _ HH) as [HAP _]. rewrite Forall_forall in HAP.
    destruct (HAP (FB, 256) ltac:(apply in_app_iff; right; left; reflexivity)) as (_ & _ & _ & FIMG).
    cbn [fst snd] in FIMG. clear HAP.
    assert (XIN' : In (X, XB) (LB ++ fdata ((FB, 256) :: LF))) by (apply in_or_app; left; exact XIN).
    assert (CX : crange CS X XB)
      by (rewrite <- Ehcs; eapply aobj_crange; eapply hm_aobj_block; [exact HH| exact XIN]).
    pose proof (wcover_of_stack asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] m m1 lo
                  (bv_unsigned sp - lo) PRES ltac:(klia) ltac:(klia)) as WCS.
    assert (KP : Z.of_nat (Z.to_nat P) = P) by lia.
    destruct (k3_split3 asegs m1 X xs1 (Z.to_nat P) ltac:(lia) XA) as (XA0 & XA1 & XA2). clear XA.
    rewrite KP in XA1. replace (X + 4 * Z.of_nat (2 * Z.to_nat P)) with (X + 4 * (2 * P)) in XA2 by lia.
    assert (LXa : length (firstn (Z.to_nat P) xs1) = Z.to_nat P) by (apply firstn_length_le; lia).
    assert (LXb : length (firstn (Z.to_nat P) (skipn (Z.to_nat P) xs1)) = Z.to_nat P)
      by (apply firstn_length_le; rewrite skipn_length; lia).
    assert (LXc : length (skipn (2 * Z.to_nat P) xs1) = (length xs1 - 2 * Z.to_nat P)%nat) by (apply skipn_length).
    set (xa := firstn (Z.to_nat P) xs1) in *. set (xb := firstn (Z.to_nat P) (skipn (Z.to_nat P) xs1)) in *.
    set (xc := skipn (2 * Z.to_nat P) xs1) in *.
    clearbody xa xb xc.
    zstep. zstep. zstep. zstep.
    pose proof (u8arr_of_u32arr asegs _ _ _ XA1) as XBU. clear XA1.
    pose proof (hm_aobj_block asegs R HIA _ _ _ _ _ _ HH XIN) as XOB.
    rewrite <- Ehcs.
    pose proof (artA_amemset asegs R HIA A_ASAN_MEMSET_KB) as SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := X + 4 * P) (v := 0) (n := 4 * P)
                     (lo := lo) (ds := u32s xb);
                   rewrite ?(unsigned_lit sp2) by exact SP2R; k3_ob).
    clear SPC. rw_hcs.
    lazymatch goal with U : u8arr asegs _ (X + 4 * P) (repeat _ _) |- _ => rename U into XZU end.
    replace (Z.to_nat (4 * P)) with (4 * Z.to_nat P)%nat in XZU by lia.
    apply k3_zeros in XZU.
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) =>
      assert (XJ : u32arr asegs mc X (xa ++ repeat (Z_to_bv 64 0) (Z.to_nat P) ++ xc)) end.
    { apply k3_join3; [exact XA0 | rewrite LXa, KP; exact XZU |].
      rewrite LXa, repeat_length, KP. replace (X + 4 * P + 4 * P) with (X + 4 * (2 * P)) by lia. exact XA2. }
    clear XA0 XZU XA2.
    remember (xa ++ repeat (Z_to_bv 64 0) (Z.to_nat P) ++ xc) as xj eqn:EXJ.
    assert (LXJ : length xj = length xs) by (subst xj; rewrite !app_length, repeat_length, LXa, LXc; lia).
    clear EXJ.
    zstep. zstep. zstep. zstep. zstep. zstep. zstep.
    pose proof (u32arr_ro asegs _ _ _ MPA) as MPB.
    lazymatch goal with HHc : HM asegs R HIA h1 LB _ ?mc |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) =>
      destruct (RTM h1 LB ((FB, 256) :: LF) mc HHc) as [RPB RPO] end.
    frame_aobj FSH (FB + 32) 4%nat as OA1.
    frame_aobj FSH (FB + 96) 5%nat as OA0.
    rewrite <- Ehcs.
    pose proof CMUL as SPC. unfold mpi_core_mul_stmtA, A_MPI_CORE_MUL in SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (X := FB + 96) (A := FB + 32) (an := P)
                     (B := RP) (bn := 2) (lo := lo) (xs := a0s) (ys := a1s) (zs := rs);
                   rewrite ?(unsigned_lit sp2) by exact SP2R; k3_ob).
    clear SPC. rw_hcs.
    lazymatch goal with U : u32arr asegs _ (FB + 96) ?l, E : length ?l = length a0s |- _ =>
      rename U into PRA; rename E into LPR; rename l into ps end.
    zstep. zstep. zstep. zstep. zstep.
    pose proof (u32arr_ro asegs _ _ _ XJ) as XJB.
    pose proof (u32arr_ro asegs _ _ _ PRA) as PRB.
    lazymatch goal with HHc : HM asegs R HIA h1 LB _ ?mc |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) =>
      pose proof (hm_aobj_block asegs R HIA _ _ _ _ _ _ HHc XIN) as XOB2; pose proof (hm_abase asegs R HIA _ _ _ _ HHc) as ABS end.
    rewrite Ehcs in XOB2.
    frame_aobj FSH (FB + 96) 5%nat as OA0'.
    pose proof CADD as SPC. unfold mpi_core_add_stmtA, A_MPI_CORE_ADD in SPC.
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) =>
      eapply evtA_cut;
      [ eapply SPC with (X := X) (A := X) (B := FB + 96) (n := P + 2) (lo := lo) (xs := xj) (ys := xj) (zs := ps);
        rewrite ?(unsigned_lit sp2) by exact SP2R; k3_ob
      | unfold mpi_core_add_postA, MPI_CORE_ADD_STACK_A; rewrite ?(unsigned_lit sp2) by qlia; post_callA asegs mc ] end.
    clear SPC.
    lazymatch goal with U : u32arr asegs _ X ?l, E : length ?l = length xj |- _ => rename U into XF; rename E into LXF end.
    eapply (kob_epi P PR XLEN h1 FB sp2).
    all: first [ eassumption
               | exact HREL | exact FBOK | exact SP2OK
               | (rewrite LXF; exact LXJ)
               | (unfold kob_rfr; repeat (first [eassumption | split])) ].
  Qed.

  Lemma kp2_split3 : forall segs mm A ws P, 0 <= P -> 2 * P <= Z.of_nat (length ws) -> u32arr segs mm A ws ->
    exists l1 l2 l3, ws = l1 ++ l2 ++ l3 /\ length l1 = Z.to_nat P /\ length l2 = Z.to_nat P /\
      u32arr segs mm A l1 /\ u32arr segs mm (A + 4 * P) l2 /\ u32arr segs mm (A + 8 * P) l3.
  Proof.
    intros segs mm A ws P HP HL H.
    assert (L1 : length (firstn (Z.to_nat P) ws) = Z.to_nat P) by (apply firstn_length_le; lia).
    assert (L2 : length (firstn (Z.to_nat P) (skipn (Z.to_nat P) ws)) = Z.to_nat P)
      by (apply firstn_length_le; rewrite length_skipn; lia).
    exists (firstn (Z.to_nat P) ws), (firstn (Z.to_nat P) (skipn (Z.to_nat P) ws)), (skipn (Z.to_nat P) (skipn (Z.to_nat P) ws)).
    rewrite <- (firstn_skipn (Z.to_nat P) ws) in H. apply u32arr_app in H. destruct H as [H1 H2]. rewrite L1 in H2.
    rewrite <- (firstn_skipn (Z.to_nat P) (skipn (Z.to_nat P) ws)) in H2. apply u32arr_app in H2. destruct H2 as [H2 H3].
    rewrite L2 in H3. rewrite Z2Nat.id in H2, H3 by exact HP.
    replace (A + 4 * P + 4 * P) with (A + 8 * P) in H3 by lia.
    refine (conj _ (conj L1 (conj L2 (conj H1 (conj H2 H3))))). rewrite !firstn_skipn. reflexivity.
  Qed.

  Lemma kp2_join3 : forall segs mm A l1 l2 l3 P, 0 <= P -> length l1 = Z.to_nat P -> length l2 = Z.to_nat P ->
    u32arr segs mm A l1 -> u32arr segs mm (A + 4 * P) l2 -> u32arr segs mm (A + 8 * P) l3 -> u32arr segs mm A (l1 ++ l2 ++ l3).
  Proof.
    intros segs mm A l1 l2 l3 P HP L1 L2 H1 H2 H3. apply (proj2 (u32arr_app segs mm A l1 (l2 ++ l3))). split; [exact H1|].
    rewrite L1, Z2Nat.id by exact HP. apply (proj2 (u32arr_app segs mm (A + 4 * P) l2 l3)). split; [exact H2|].
    rewrite L2, Z2Nat.id by exact HP. replace (A + 4 * P + 4 * P) with (A + 8 * P) by lia. exact H3.
  Qed.

  Lemma kp2_zero32 : forall segs mm A P, 0 <= P ->
    u8arr segs mm A (repeat (Z_to_bv 8 0) (Z.to_nat (4 * P))) -> u32arr segs mm A (repeat (Z_to_bv 64 0) (Z.to_nat P)).
  Proof.
    intros segs mm A P HP H. apply u32arr_of_u8arr_u32s. rewrite u32s_repeat0.
    replace (4 * Z.to_nat P)%nat with (Z.to_nat (4 * P)) by lia. exact H.
  Qed.

  Ltac kp2_dlia := first [ klia | match goal with D : _ \/ _ |- _ => revert D; klia end ].

  Ltac kp2_ob :=
    first [ left; first [ rewrite AMS | rewrite AMC ]; reflexivity
          | reflexivity
          | eassumption
          | rw_hcs; eassumption
          | apply u32arr_ro; eassumption
          | lazymatch goal with |- crange _ _ _ =>
              try rw_hcs; eapply crange_sub; [match goal with S : crange _ lo (bv_unsigned sp - lo) |- _ => exact S end | klia | klia] end
          | lazymatch goal with |- client_wrange _ _ _ _ ?A _ =>
              match goal with I : In (?B, ?k) _ |- _ => eapply (client_wrange_block _ _ _ _ A _ B k I); klia end end
          | lazymatch goal with |- _ <= htop _ _ _ _ => rw_htop; klia end
          | lazymatch goal with |- aobj _ _ _ _ _ _ =>
              first [ match goal with O : aobj _ _ _ _ _ _ |- _ => eapply aobj_sub; [exact O | klia | klia] end
                    | rw_hcs; match goal with O : aobj _ _ _ _ _ _ |- _ => eapply aobj_sub; [exact O | klia | klia] end ] end
          | lazymatch goal with |- @eq (bv _) _ _ => f_equal; klia end
          | lazymatch goal with |- bv_unsigned _ mod 2 = 0 => vm_compute; reflexivity end
          | left; split; reflexivity
          | split; klia
          | kp2_dlia
          | left; kp2_dlia | right; kp2_dlia | right; left; kp2_dlia | right; right; kp2_dlia ].

  Ltac kp2_mem :=
    first [ eassumption
          | match goal with H : rw_cells _ ?mm ?a ?cs |- rw_cells _ ?mm ?b ?cs => replace b with a by klia; exact H end
          | match goal with H : stk _ ?mm ?a ?c |- stk _ ?mm ?b ?d => replace b with a by klia; replace d with c by klia; exact H end ].

  Lemma kob_pass2 : forall (P : Z), 6 <= P <= 8 -> 2 * P <= Z.of_nat (length xs) ->
    forall (h1 : HST asegs R HIA) (FB sp2 : Z) (m1 : mem) (xs1 a1s a0s : list word) (w0 w1 w2 : word)
           (ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v4 v10 t3 t4 t5 t6 : word),
    HM asegs R HIA h1 LB ((FB, 256) :: LF) m1 -> kob_hrel h1 -> kob_fbok FB -> kob_sp2ok sp2 ->
    mem_inv asegs m1 ->
    presW asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] m m1 ->
    u32arr asegs m1 X xs1 -> length xs1 = length xs ->
    rw_cells asegs m1 (Z.shiftr FB 3 + al_sb AL) (kob_meta 0) ->
    rw_cells asegs m1 FB [C8 w0; C8 w1; C8 w2] ->
    u32arr asegs m1 (FB + 32) a1s -> length a1s = Z.to_nat P ->
    u32arr asegs m1 (FB + 96) a0s -> length a0s = Z.to_nat (P + 2) ->
    kob_rfr P FB sp2 m1 ->
    evtA asegs AL CS (Q P)
      (MS (mkR ra1 (Z_to_bv 64 sp2) gp tp t0 t1 t2 sp (Z_to_bv 64 sp2) a0 a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 (FB + 32)) (Z_to_bv 64 (P + 2)) v4 (Z_to_bv 64 RP) (Z_to_bv 64 X) (Z_to_bv 64 P)
               (Z_to_bv 64 (FB + 96)) (Z_to_bv 64 (4 * P)) v10 (Z_to_bv 64 (Z.shiftr FB 3 + al_sb AL)) t3 t4 t5 t6)
          F (Z_to_bv 64 0xd7524) fc None m1 (seg_rom asegs)).
  Proof.
    intros P PR XLEN h1 FB sp2 m1 xs1 a1s a0s w0 w1 w2 ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v4 v10 t3 t4 t5 t6
      HH KHR FOK SPOK MI PRES XA XL1 FSH FHD A1A LA1 A0A LA0 RFR.
    rt_facts.
    pose proof KHR as KHR0. destruct KHR0 as (Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI).
    pose proof FOK as FOK0.
    destruct FOK0 as (FRSH & F64 & F8 & FB0 & FBLO & CFB & INH & IND & FLF & FLB & FCE & FDT & SBND & APS & XFB & XM).
    pose proof SPOK as SPOK0. destruct SPOK0 as (SP2M & SP2).
    destruct RFR as (ST1 & ST2 & RS1 & ST3 & RS2 & ST4 & SAV).
    pose proof RT as RT0. destruct RT0 as (LRS & RP0 & RPA & RPLO & RPHI & RTH).
    pose proof (hm_top asegs R HIA _ _ _ _ HH) as HTOP. rewrite Ehtop, Estk in HTOP.
    destruct (x_facts _ _ _ _ HH XIN) as [X0 XCE].
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| klia| klia]).
    assert (SP2R : 0 <= sp2 < 2^64) by (clear - SP2 SPR SLO LOS ALO ACV NEEDR NER; lia).
    pose proof (alloc_ceiling_top47 (L := arl_L R)) as AC47.
    pose proof (hm_wlow asegs R HIA _ _ _ _ HH) as WL0.
    assert (WL : wlow R LB LF).
    { destruct WL0 as [BL DL]. split; [|exact DL]. unfold blocks_low in BL |- *. intros B j HIn. apply BL.
      apply in_app_iff in HIn. apply in_app_iff. destruct HIn as [HIn|HIn]; [left; exact HIn| right; right; exact HIn]. }
    clear WL0.
    pose proof (art_alwf asegs R HIA) as ALWF.
    assert (XIN2 : In (X, XB) (LB ++ fdata ((FB, 256) :: LF))) by (apply in_or_app; left; exact XIN).
    assert (RPFB : RP + 8 <= FB \/ FB + 256 <= RP).
    { destruct (hm_apart asegs R HIA _ _ _ _ HH) as [HB _]. rewrite Forall_forall in HB.
      destruct (HB (FB, 256) ltac:(apply in_app_iff; right; left; reflexivity)) as (_ & _ & _ & HI).
      cbn [fst snd] in HI. clear - HI RPLO RPHI. lia. }
    unfold kob_meta in FSH; cbn [repeat app] in FSH.
    pose (lxi := lxA_img (arl_AL R) IMG).
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_ASAN_MEMSET_KB; 0xd7770] [] 200%N). lx_tree.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m1; rn_frame FB.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m2 end.
    lazymatch goal with H : u32arr asegs m2 X xs1 |- _ =>
      destruct (kp2_split3 asegs m2 X xs1 P ltac:(lia) ltac:(rewrite XL1; lia) H) as (l1 & l2 & l3 & EX1 & L1 & L2 & XP1 & XP2 & XP3);
      clear H end.
    assert (L3 : length l3 = (length xs - 2 * Z.to_nat P)%nat) by (rewrite <- XL1, EX1, !length_app, L1, L2; lia).
    pose proof (u8arr_of_u32arr asegs _ _ _ XP2) as XU2.
    assert (LU2 : length (u32s l2) = (4 * Z.to_nat P)%nat) by (rewrite u32s_length; lia).
    lazymatch goal with H : HM _ _ _ h1 _ _ m2 |- _ => pose proof (hm_aobj_block asegs R HIA _ _ _ _ _ _ H XIN) as OXB end.
    rewrite Ehcs in OXB.
    rewrite <- Ehcs.
    pose proof (artA_amemset asegs R HIA A_ASAN_MEMSET_KB) as SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := X + 4 * P) (v := 0) (n := 4 * P) (lo := lo) (ds := u32s l2);
      rewrite ?(unsigned_lit sp2) by exact SP2R; kp2_ob).
    clear SPC; rw_hcs.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m3 end.
    lazymatch goal with H : u8arr asegs m3 (X + 4 * P) (repeat _ _) |- _ =>
      apply (kp2_zero32 asegs m3 (X + 4 * P) P ltac:(lia)) in H; rename H into XZ end.
    pose proof (kp2_join3 asegs m3 X l1 (repeat (Z_to_bv 64 0) (Z.to_nat P)) l3 P ltac:(lia) L1 (repeat_length _ _) XP1 XZ XP3) as XA.
    clear XP1 XP3 XZ OXB. try clear XU2. try clear XP2.
    set (xs2 := l1 ++ repeat (Z_to_bv 64 0) (Z.to_nat P) ++ l3) in XA.
    assert (LX2 : length xs2 = length xs) by (unfold xs2; rewrite <- XL1, EX1, !length_app, repeat_length, L1, L2; lia).
    clearbody xs2.
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_MPI_CORE_MUL; 0xd7770] [] 200%N). lx_tree.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m3; rn_frame FB.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m4 end.
    lazymatch goal with H : HM _ _ _ h1 _ _ m4 |- _ => destruct (RTH h1 _ _ _ H) as [RB RO] end.
    rewrite Ehcs in RO.
    frame_aobj FSH (FB + 96) 5%nat as OA0.
    frame_aobj FSH (FB + 32) 4%nat as OA1.
    rewrite <- Ehcs.
    pose proof CMUL as SPC. unfold mpi_core_mul_stmtA, A_MPI_CORE_MUL, MPI_CORE_MUL_STACK_A in SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (X := FB + 96) (A := FB + 32) (an := P) (B := RP) (bn := 2)
        (lo := lo) (xs := a0s) (ys := a1s) (zs := rs);
      rewrite ?(unsigned_lit sp2) by exact SP2R; kp2_ob).
    clear SPC; rw_hcs.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m5 end.
    lazymatch goal with H : u32arr asegs m5 (FB + 96) ?l, E : length ?l = length a0s |- _ =>
      rename H into A0B; rename E into LA0B; rename l into a0s2 end.
    rewrite LA0 in LA0B.
    try clear RB. try clear RO. try clear OA0. try clear OA1.
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_MPI_CORE_ADD; 0xd7770] [] 200%N). lx_tree.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m5; rn_frame FB.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m5b end.
    lazymatch goal with H : HM _ _ _ h1 _ _ m5b |- _ =>
      pose proof (hm_aobj_block asegs R HIA _ _ _ _ _ _ H XIN) as OXB5; pose proof (hm_abase asegs R HIA _ _ _ _ H) as AB5 end.
    rewrite Ehcs in OXB5.
    frame_aobj FSH (FB + 96) 5%nat as OA05.
    pose proof CADD as SPC. unfold mpi_core_add_stmtA, mpi_core_add_postA, A_MPI_CORE_ADD, MPI_CORE_ADD_STACK_A in SPC.
    callxA_sp sp2 (eapply SPC with (CS := CS) (X := X) (A := X) (B := FB + 96) (n := P + 2) (lo := lo) (xs := xs2) (ys := xs2) (zs := a0s2);
      rewrite ?(unsigned_lit sp2) by exact SP2R; kp2_ob).
    clear SPC.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m6 end.
    lazymatch goal with H : u32arr asegs m6 X ?l, E : length ?l = length xs2 |- _ =>
      rename H into XA6; rename E into LX6; rename l into xs3 end.
    rewrite LX2 in LX6.
    clear OXB5 AB5 OA05.
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_ASAN_MEMCPY_KB; 0xd7770] [] 200%N). lx_tree.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m6; rn_frame FB.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m7 end.
    lazymatch goal with H : u32arr asegs m7 X xs3 |- _ =>
      destruct (u32arr_mid asegs m7 X xs3 (Z.to_nat P) (Z.to_nat P) ltac:(lia) H) as [XM7 LM7] end.
    rewrite Z2Nat.id in XM7 by lia.
    pose proof (u32arr_ro asegs _ _ _ XM7) as XB7.
    lazymatch goal with H : u32arr asegs m7 (FB + 32) a1s |- _ => pose proof (u8arr_of_u32arr asegs _ _ _ H) as A1U end.
    assert (LU1 : length (u32s a1s) = (4 * Z.to_nat P)%nat) by (rewrite u32s_length; lia).
    assert (LU7 : length (u32s (firstn (Z.to_nat P) (skipn (Z.to_nat P) xs3))) = (4 * Z.to_nat P)%nat)
      by (rewrite u32s_length, LM7; lia).
    lazymatch goal with H : HM _ _ _ h1 _ _ m7 |- _ => pose proof (hm_aobj_block asegs R HIA _ _ _ _ _ _ H XIN) as OXB7 end.
    rewrite Ehcs in OXB7.
    frame_aobj FSH (FB + 32) 4%nat as OA17.
    rewrite <- Ehcs.
    pose proof (artA_amemcpy asegs R HIA A_ASAN_MEMCPY_KB) as SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := FB + 32) (SRC := X + 4 * P) (n := 4 * P) (lo := lo)
        (ds := u32s a1s) (ss := u32s (firstn (Z.to_nat P) (skipn (Z.to_nat P) xs3)));
      rewrite ?(unsigned_lit sp2) by exact SP2R; kp2_ob).
    clear SPC; rw_hcs.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m8 end.
    lazymatch goal with H : u8arr asegs m8 (FB + 32) (u32s ?l) |- _ => apply u32arr_of_u8arr_u32s in H; rename H into A1B end.
    try clear XM7. try clear XB7. try clear A1U. try clear OXB7. try clear OA17.
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [0xd75c4; 0xd7770] [] 200%N). lx_tree.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m8; rn_frame FB.
    replace (4 * P + X) with (X + 4 * P) in * by lia.
    eapply (kob_pass3 P).
    all: first [ eassumption | exact FOK | exact SPOK | exact KHR
               | unfold kob_meta; cbn [repeat app]; eassumption
               | unfold kob_rfr; repeat match goal with |- _ /\ _ => split end; kp2_mem ].
  Qed.

  Lemma k1_u32arr_split3 : forall segs m A ws (k j : nat), (k + j <= length ws)%nat -> u32arr segs m A ws ->
    exists w0 w1 w2, length w0 = k /\ length w1 = j /\ length w2 = (length ws - k - j)%nat /\
      u32arr segs m A w0 /\ u32arr segs m (A + 4 * Z.of_nat k) w1 /\ u32arr segs m (A + 4 * Z.of_nat (k + j)) w2.
  Proof.
    intros sg mm AA ws k j Hl H.
    exists (firstn k ws), (firstn j (skipn k ws)), (skipn j (skipn k ws)).
    assert (L0 : length (firstn k ws) = k) by (apply firstn_length_le; lia).
    assert (L1 : length (firstn j (skipn k ws)) = j) by (apply firstn_length_le; rewrite skipn_length; lia).
    rewrite <- (firstn_skipn k ws) in H. apply u32arr_app in H. rewrite L0 in H. destruct H as [H0 H].
    rewrite <- (firstn_skipn j (skipn k ws)) in H. apply u32arr_app in H. rewrite L1 in H. destruct H as [H1 H2].
    split; [exact L0|]. split; [exact L1|]. split; [rewrite !skipn_length; lia|].
    split; [exact H0|]. split; [exact H1|].
    replace (AA + 4 * Z.of_nat (k + j)) with (AA + 4 * Z.of_nat k + 4 * Z.of_nat j) by lia. exact H2.
  Qed.

  Tactic Notation "k1_rn" hyp(H) ident(N) := first [ rename H into N | clear N; rename H into N | idtac ].

  Ltac k1_names FB sp2 :=
    let mx := curmem in
    repeat match goal with H : ?T, H' : ?T |- _ => lazymatch type of T with Prop => clear H' end end;
    try (match goal with H : HM _ _ _ _ _ _ mx |- _ => k1_rn H HH1 end);
    try (match goal with H : mem_inv _ mx |- _ => k1_rn H MI end);
    try (match goal with H : presW _ _ _ _ _ _ _ _ _ _ mx |- _ => k1_rn H PRES end);
    try (match goal with H : abase _ _ mx |- _ => k1_rn H ABS end);
    try (match goal with H : u32arr _ mx X _ |- _ => k1_rn H XA end);
    try (match goal with H : u32arr _ mx (X + 8 * _) _ |- _ => k1_rn H XAU end);
    try (match goal with H : u32arr _ mx (FB + 32) _ |- _ => k1_rn H MPA end);
    try (match goal with H : u32arr _ mx (FB + 96) _ |- _ => k1_rn H RPA end);
    try (match goal with H : rw_cells _ mx (Z.shiftr FB 3 + al_sb _) _ |- _ => k1_rn H FSH end);
    try (match goal with H : rw_cells _ mx FB _ |- _ => k1_rn H FHD end);
    try (match goal with H : stk _ mx lo sp2 |- _ => k1_rn H ST1 end);
    try (match goal with H : stk _ mx sp2 (sp2 + 24) |- _ => k1_rn H ST2 end);
    try (match goal with H : rw_cells _ mx (sp2 + 24) _ |- _ => k1_rn H SL1 end);
    try (match goal with H : stk _ mx (sp2 + 40) (sp2 + 72) |- _ => k1_rn H ST3 end);
    try (match goal with H : rw_cells _ mx (sp2 + 72) _ |- _ => k1_rn H SL2 end);
    try (match goal with H : stk _ mx (sp2 + 128) _ |- _ => k1_rn H ST4 end);
    try (match goal with H : rw_cells _ mx (bv_unsigned sp - 104) _ |- _ => k1_rn H SAVE end).

  Ltac k1_clean P FB sp2 :=
    try (match goal with E : ?mx = ?m0 |- _ => is_var mx; lazymatch type of mx with mem => subst mx end end);
    repeat match goal with H : lxr_okw _ |- _ => clear H end;
    repeat match goal with H : ?a = ?a |- _ => clear H end;
    repeat match goal with H : context [4 * P + X] |- _ => clear H end;
    repeat match goal with H : context [8 * P + X] |- _ => clear H end;
    repeat match goal with H : context [bv_unsigned sp + -104] |- _ => clear H end;
    k1_names FB sp2;
    try replace (4 * P + X) with (X + 4 * P) by lia.

  Ltac k1_disj_goal := first [ left; klia | right; klia | right; left; klia | right; right; klia ].
  Ltac k1_disj :=
    first [ k1_disj_goal
          | match goal with D : ?a <= ?b \/ ?c <= ?d |- _ \/ _ => destruct D as [D|D]; k1_disj_goal end ].

  Ltac k1_ob :=
    first [ reflexivity
          | eassumption
          | rw_hcs; eassumption
          | left; first [ rewrite AMS | rewrite AMC ]; reflexivity
          | left; split; reflexivity
          | match goal with H : u32arr _ ?mm ?A ?l |- bytes_at _ ?mm ?A (u32s ?l) => exact (proj1 H) end
          | exact (art_alwf asegs R HIA)
          | lazymatch goal with |- crange _ _ _ =>
              first [ rw_hcs | idtac ];
              eapply crange_sub; [match goal with S : crange _ lo (bv_unsigned sp - lo) |- _ => exact S end | klia | klia] end
          | lazymatch goal with |- client_wrange _ _ _ _ ?A _ =>
              match goal with I : In (?B, ?k) _ |- _ => eapply (client_wrange_block _ _ _ _ A _ B k I); klia end end
          | lazymatch goal with |- _ <= htop _ _ _ _ => rw_htop; klia end
          | lazymatch goal with |- bv_unsigned _ mod 2 = 0 => rewrite unsigned_lit by klia; reflexivity end
          | klia
          | k1_disj
          | lazymatch goal with |- Z_to_bv _ _ = Z_to_bv _ _ => f_equal; klia end
          | match goal with |- ?g => idtac "K1OB-LEFT" g end ].

  Lemma kob_pass1 : forall (P : Z), 6 <= P <= 8 -> 2 * P <= Z.of_nat (length xs) ->
    forall (h1 : HST asegs R HIA) (FB sp2 : Z) (m1 : mem) (xs1 a1s a0s : list word) (w0 w1 w2 : word)
           (ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v6 v8 v10 t3 t4 t5 t6 : word),
    HM asegs R HIA h1 LB ((FB, 256) :: LF) m1 -> kob_hrel h1 -> kob_fbok FB -> kob_sp2ok sp2 ->
    mem_inv asegs m1 ->
    presW asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] m m1 ->
    u32arr asegs m1 X xs1 -> length xs1 = length xs ->
    rw_cells asegs m1 (Z.shiftr FB 3 + al_sb AL) (kob_meta 0) ->
    rw_cells asegs m1 FB [C8 w0; C8 w1; C8 w2] ->
    u32arr asegs m1 (FB + 32) a1s -> length a1s = Z.to_nat P ->
    u32arr asegs m1 (FB + 96) a0s -> length a0s = Z.to_nat (P + 2) ->
    kob_rfr P FB sp2 m1 ->
    evtA asegs AL CS (Q P)
      (MS (mkR ra1 (Z_to_bv 64 sp2) gp tp t0 t1 t2 sp (Z_to_bv 64 sp2) a0 a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 (FB + 32)) (Z_to_bv 64 (P + 2)) (Z_to_bv 64 X) (Z_to_bv 64 (X + 4 * P)) v6 (Z_to_bv 64 P)
               v8 (Z_to_bv 64 (4 * P)) v10 (Z_to_bv 64 (Z.shiftr FB 3 + al_sb AL)) t3 t4 t5 t6)
          F (Z_to_bv 64 0xd74c8) fc None m1 (seg_rom asegs)).
  Proof.
    intros P PR XLEN h1 FB sp2 m1 xs1 a1s a0s w0 w1 w2 ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v6 v8 v10 t3 t4 t5 t6
           HH1 HREL FBOK SP2OK MI PRES XA XL1 FSH FHD MPA MPL RPA RPL0 RFR.
    rt_facts.
    pose proof HREL as HREL'. destruct HREL' as (Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI).
    pose proof FBOK as FBOK'.
    destruct FBOK' as (FRSH & F64 & F8 & FB0 & FBLO & CFB & INH & IND & FLF & FLB & FCE & FDA & SBND & APS & XFB & XM).
    pose proof SP2OK as SP2OK'. destruct SP2OK' as (SP2M & SP2).
    destruct RFR as (ST1 & ST2 & SL1 & ST3 & SL2 & ST4 & SAVE).
    pose proof (hm_top asegs R HIA h1 _ _ _ HH1) as HTOP. rewrite Ehtop, Estk in HTOP.
    destruct (x_facts _ _ _ _ HH1 XIN) as [X0 XCE].
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| qlia| qlia]).
    assert (SP2R : 0 <= sp2 < 2^64) by (clear - SP2 SPR SLO LOS ALO ACV NEEDR NER; lia).
    assert (WL : wlow R LB LF) by (split; [exact (proj2 (proj2 (proj2 PRES)))| apply (art_data_lo asegs R HIA)]).
    assert (CX : crange CS X XB) by (rewrite <- Ehcs; eapply aobj_crange; eapply hm_aobj_block; [exact HH1| exact XIN]).
    assert (XIN2 : In (X, XB) (LB ++ fdata ((FB, 256) :: LF))) by (apply in_or_app; left; exact XIN).
    pose proof (alloc_ceiling_top47 (L := arl_L R)) as AC47.
    pose proof (art_stk_high asegs R HIA) as STKH.
    assert (RPFB : RP + 8 <= FB \/ FB + 256 <= RP).
    { destruct (hm_apart asegs R HIA h1 _ _ _ HH1) as [HB _]. rewrite Forall_forall in HB.
      destruct (HB (FB, 256) ltac:(apply in_app_iff; right; left; reflexivity)) as (_ & _ & _ & KI). cbn [fst snd] in KI.
      destruct RT as (_ & _ & _ & RL & RH & _). clear - KI RL RH. lia. }
    destruct (k1_u32arr_split3 asegs m1 X xs1 (Z.to_nat P) (Z.to_nat P) ltac:(lia) XA)
      as (xl & xm & xu & LXL & LXM & LXU & XAL0 & XAM & XAU).
    clear XA.
    rewrite Z2Nat.id in XAM by lia.
    replace (X + 4 * Z.of_nat (Z.to_nat P + Z.to_nat P)) with (X + 8 * P) in XAU by lia.
    assert (LXLz : Z.of_nat (length xl) = P) by lia.
    assert (LXMz : Z.of_nat (length xm) = P) by lia.
    assert (LXUz : Z.of_nat (length xu) = Z.of_nat (length xs) - 2 * P) by lia.
    unfold kob_meta in FSH; cbn [repeat app] in FSH.
    pose (lxi := lxA_img (arl_AL R) IMG).
    lx_hide1 CX. lx_hide1 XIN2. lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_ASAN_MEMSET_KB; 0xd7770] [] 200%N). lx_tree.
    all: unfold lx_hidden in CX, XIN2.
    all: try carryX.
    all: lxr_leaf; lxe_leaf_gc.
    k1_clean P FB sp2.
    pose proof (u8arr_of_u32arr asegs m1 (X + 4 * P) xm XAM) as XMB.
    assert (LXMB : Z.of_nat (length (u32s xm)) = 4 * P) by (rewrite u32s_length; lia).
    assert (OXM : aobj asegs AL CS m1 (X + 4 * P) (4 * P))
      by (rewrite <- Ehcs; eapply aobj_sub; [eapply hm_aobj_block; [exact HH1| exact XIN] | lia | lia]).
    clear XAM.
    rewrite <- Ehcs.
    pose proof (artA_amemset asegs R HIA A_ASAN_MEMSET_KB) as SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := X + 4 * P) (v := 0) (n := 4 * P)
                     (lo := lo) (ds := u32s xm);
      rewrite ?(unsigned_lit sp2) by exact SP2R; amem_ob).
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "MEMSET-LEFT:" g end.
    clear SPC; rw_hcs.
    k1_clean P FB sp2.
    lazymatch goal with H : u8arr asegs _ (X + 4 * P) (repeat _ _) |- _ => rename H into XMZ end.
    destruct (MpiWalkAux.u32arr_of_u8arr asegs _ (X + 4 * P) _ (Z.to_nat P) XMZ ltac:(rewrite repeat_length; lia))
      as (xm1 & XAM1 & LXM1).
    clear XMZ LXMB OXM.
    assert (LXM1z : Z.of_nat (length xm1) = P) by lia.
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) => rename mc into m2 end.
    lx_hide1 CX. lx_hide1 XIN2. lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_MPI_CORE_MUL; 0xd7770] [] 200%N). lx_tree.
    all: unfold lx_hidden in CX, XIN2.
    all: try carryX.
    all: lxr_leaf; lxe_leaf_gc.
    k1_clean P FB sp2.
    pose proof RT as RT'. destruct RT' as (RLEN & RP0 & RPM & RPL1 & RPH & RTF).
    destruct (RTF h1 LB ((FB, 256) :: LF) m2 HH1) as [RPBY RPOB].
    frame_aobj FSH (FB + 96) 5%nat as ORP.
    frame_aobj FSH (FB + 32) 4%nat as OMP.
    assert (ORP1 : aobj asegs AL CS m2 (FB + 96) (4 * (P + 2))) by (eapply aobj_sub; [exact ORP| lia| lia]).
    assert (OMP1 : aobj asegs AL CS m2 (FB + 32) (4 * P)) by (eapply aobj_sub; [exact OMP| lia| lia]).
    clear ORP OMP.
    assert (CMSA : MPI_CORE_MUL_STACK_A = 240) by reflexivity.
    pose proof CMUL as SPM. unfold mpi_core_mul_stmtA in SPM.
    rewrite <- Ehcs.
    callxA_sp sp2 (eapply SPM with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (X := FB + 96) (A := FB + 32) (an := P)
                     (B := RP) (bn := 2) (lo := lo) (xs := a0s) (ys := a1s) (zs := rs);
      rewrite ?(unsigned_lit sp2) by exact SP2R; k1_ob).
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "CMUL-LEFT:" g end.
    clear SPM RPOB RPBY; rw_hcs.
    k1_clean P FB sp2.
    lazymatch goal with H : u32arr asegs _ (FB + 96) ?l |- _ => rename l into a0s2 end.
    assert (LRPA : length a0s2 = Z.to_nat (P + 2))
      by (match goal with H : length a0s2 = length a0s |- _ => rewrite H end; exact RPL0).
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) => rename mc into m3 end.
    lx_hide1 CX. lx_hide1 XIN2. lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_MPI_CORE_ADD; 0xd7770] [] 200%N). lx_tree.
    all: unfold lx_hidden in CX, XIN2.
    all: try carryX.
    all: lxr_leaf; lxe_leaf_gc.
    k1_clean P FB sp2.
    assert (XLM : u32arr asegs m3 X (xl ++ xm1)) by (apply u32arr_app; split; [exact XA | rewrite LXLz; exact XAM1]).
    clear XA XAM1. rename XLM into XA.
    assert (LXA : Z.of_nat (length (xl ++ xm1)) = 2 * P) by (rewrite app_length; lia).
    assert (OXA : aobj asegs AL CS m3 X (4 * (P + 2)))
      by (rewrite <- Ehcs; eapply aobj_sub; [eapply hm_aobj_block; [exact HH1| exact XIN] | lia | lia]).
    frame_aobj FSH (FB + 96) 5%nat as ORP.
    assert (ORP2 : aobj asegs AL CS m3 (FB + 96) (4 * (P + 2))) by (eapply aobj_sub; [exact ORP| lia| lia]).
    clear ORP.
    pose proof (hm_abase asegs R HIA h1 _ _ _ HH1) as ABm.
    assert (CASA : MPI_CORE_ADD_STACK_A = 80) by reflexivity.
    pose proof CADD as SPD. unfold mpi_core_add_stmtA in SPD.
    callxA_sp sp2 (eapply SPD with (CS := CS) (X := X) (A := X) (B := FB + 96) (n := P + 2) (lo := lo)
                     (xs := xl ++ xm1) (ys := xl ++ xm1) (zs := a0s2);
      rewrite ?(unsigned_lit sp2) by exact SP2R; k1_ob).
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "CADD-LEFT:" g end.
    clear SPD.
    k1_clean P FB sp2.
    lazymatch goal with H : u32arr asegs _ X ?l |- _ => rename l into xs3 end.
    assert (LXS3 : Z.of_nat (length xs3) = 2 * P)
      by (match goal with H : length xs3 = length (xl ++ xm1) |- _ => rewrite H end; exact LXA).
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) => rename mc into m4 end.
    lx_hide1 CX. lx_hide1 XIN2. lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_ASAN_MEMCPY_KB; 0xd7770] [] 200%N). lx_tree.
    all: unfold lx_hidden in CX, XIN2.
    all: try carryX.
    all: lxr_leaf; lxe_leaf_gc.
    k1_clean P FB sp2.
    destruct (u32arr_mid asegs m4 X xs3 (Z.to_nat P) (Z.to_nat P) ltac:(lia) XA) as [XMID LMID].
    rewrite Z2Nat.id in XMID by lia.
    pose proof (u8arr_of_u32arr asegs m4 (FB + 32) a1s MPA) as MPB.
    assert (LMPB : Z.of_nat (length (u32s a1s)) = 4 * P) by (rewrite u32s_length; lia).
    assert (LSRC : Z.of_nat (length (u32s (firstn (Z.to_nat P) (skipn (Z.to_nat P) xs3)))) = 4 * P)
      by (rewrite u32s_length; lia).
    frame_aobj FSH (FB + 32) 4%nat as OMP.
    assert (OMP2 : aobj asegs AL CS m4 (FB + 32) (4 * P)) by (eapply aobj_sub; [exact OMP| lia| lia]).
    assert (OXS : aobj asegs AL CS m4 (X + 4 * P) (4 * P))
      by (rewrite <- Ehcs; eapply aobj_sub; [eapply hm_aobj_block; [exact HH1| exact XIN] | lia | lia]).
    clear OMP MPA.
    rewrite <- Ehcs.
    pose proof (artA_amemcpy asegs R HIA A_ASAN_MEMCPY_KB) as SPC.
    callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := FB + 32) (SRC := X + 4 * P)
                     (n := 4 * P) (lo := lo) (ds := u32s a1s) (ss := u32s (firstn (Z.to_nat P) (skipn (Z.to_nat P) xs3)));
      rewrite ?(unsigned_lit sp2) by exact SP2R; k1_ob).
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "MEMCPY-LEFT:" g end.
    clear SPC; rw_hcs.
    k1_clean P FB sp2.
    lazymatch goal with H : u8arr asegs _ (FB + 32) _ |- _ => rename H into MPZ end.
    pose proof (u32arr_of_u8arr_u32s asegs _ (FB + 32) _ MPZ) as MPA. clear MPZ.
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mc _) => rename mc into m5 end.
    assert (XFIN : u32arr asegs m5 X (xs3 ++ xu)).
    { apply u32arr_app. split; [exact XA|]. replace (X + 4 * Z.of_nat (length xs3)) with (X + 8 * P) by lia. exact XAU. }
    assert (LXFIN : length (xs3 ++ xu) = length xs) by (rewrite app_length; lia).
    clear XA XAU XMID.
    lazymatch goal with |- evtA _ _ _ (Q ?p) _ => eapply (kob_pass2 p) end.
    all: first [ eassumption
               | unfold kob_meta; cbn [repeat app]; eassumption
               | unfold kob_rfr; repeat (first [assumption | split])
               | match goal with |- ?g => idtac "PASS2-LEFT" g end ].
  Qed.

  Lemma kh_stk2 : forall (mq : mem) (p1 p2 p3 : Z) (cs : list cell), stk asegs mq p1 p2 -> rw_cells asegs mq p2 cs ->
    p2 + Z.of_nat (cells_size cs) = p3 -> p1 <= p2 -> stk asegs mq p1 p3.
  Proof.
    intros mq p1 p2 p3 cs H1 H2 E Hab. pose proof (stk_release asegs mq p1 p2 cs H1 H2 Hab) as H3. rewrite E in H3. exact H3.
  Qed.

  Lemma kh_stk3 : forall (mq : mem) (p1 p2 p3 p4 : Z) (cs : list cell), stk asegs mq p1 p2 -> rw_cells asegs mq p2 cs ->
    stk asegs mq p3 p4 -> p2 + Z.of_nat (cells_size cs) = p3 -> p1 <= p2 -> p3 <= p4 -> stk asegs mq p1 p4.
  Proof.
    intros mq p1 p2 p3 p4 cs H1 H2 H3 E Hab Hcd. pose proof (kh_stk2 mq p1 p2 p3 cs H1 H2 E Hab) as H4.
    eapply stk_merge; [exact H4 | exact H3 | lia].
  Qed.

  Lemma kh_wlow : forall (LB0 LF0 : list blk) (b : blk), wlow R LB0 (b :: LF0) -> wlow R LB0 LF0.
  Proof.
    intros LB0 LF0 b HW. unfold wlow, blocks_low in *. destruct HW as [BL DL]. split; [| exact DL].
    intros B j HI. apply BL. apply in_app_iff in HI. apply in_app_iff.
    destruct HI as [HI|HI]; [left; exact HI | right; right; exact HI].
  Qed.

  Ltac kh_tocb A H :=
    match goal with U : u8arr asegs _ A _ |- _ =>
      apply (rw_cells_of_u8arr asegs) in U; rewrite repeat_length in U;
      cbn [Z.to_nat Pos.to_nat Pos.iter_op Nat.add] in U; rename U into H
    end.

  Ltac kh_tow A H :=
    match goal with U : u8arr asegs _ A (u32s _) |- _ => apply u32arr_of_u8arr_u32s in U; rename U into H end.

  Lemma kh_rfr_lo : forall (mq : mem) (SB hi : Z) (v1 v2 v3 v4 v5 v6 : word),
    stk asegs mq SB (SB + 16) -> rw_cells asegs mq (SB + 16) [C8 v1; C8 v2; C8 v3; C8 v4; C8 v5; C8 v6] ->
    stk asegs mq (SB + 64) hi -> SB + 64 <= hi ->
    stk asegs mq SB (SB + 24) /\ rw_cells asegs mq (SB + 24) [C8 v2; C8 v3] /\ stk asegs mq (SB + 40) hi.
  Proof.
    intros mq SB hi v1 v2 v3 v4 v5 v6 H1 H2 H3 Hle.
    destruct (rw_cells_split3 asegs mq (SB + 16) [C8 v1] [C8 v2; C8 v3] [C8 v4; C8 v5; C8 v6] H2) as (A1 & A2 & A3).
    lazymatch type of A2 with rw_cells _ _ ?a _ => replace a with (SB + 24) in A2 by (cbn [cells_size csize Nat.add]; lia) end.
    lazymatch type of A3 with rw_cells _ _ ?a _ => replace a with (SB + 40) in A3 by (cbn [cells_size csize Nat.add]; lia) end.
    pose proof (stk_of_rw_cells asegs mq (SB + 40) _ A3) as A4.
    lazymatch type of A4 with stk _ _ _ ?a => replace a with (SB + 64) in A4 by (cbn [cells_size csize Nat.add]; lia) end.
    split; [| split; [exact A2 |]].
    - eapply kh_stk2; [exact H1 | exact A1 | cbn [cells_size csize Nat.add]; lia | lia].
    - eapply stk_merge; [exact A4 | exact H3 | lia].
  Qed.

  Ltac kh_rfr SB :=
    let mx := curmem in
    match goal with
    | H1 : stk asegs mx SB (SB + 16), H2 : rw_cells asegs mx (SB + 16) _, H3 : stk asegs mx (SB + 64) ?hi |- _ =>
        destruct (kh_rfr_lo mx SB hi _ _ _ _ _ _ H1 H2 H3 ltac:(lia)) as (RFA & RFB & RFC); clear H1 H2 H3
    end.

  Ltac kh_a0s A :=
    match goal with RW : rw_cells asegs ?mx A [CB 40 _] |- evtA _ _ _ (Q ?p) _ =>
      let ZU := fresh "ZU" in
      pose proof (u8arr_of_rw_cells asegs _ _ _ _ RW) as ZU;
      apply (u8arr_zero_prefix asegs mx A 40%nat (4 * Z.to_nat (p + 2)) ltac:(cbn; lia)) in ZU;
      rewrite <- u32s_repeat0 in ZU; apply u32arr_of_u8arr_u32s in ZU
    end.

  Ltac kh_carryW A H :=
    match goal with
    | UA : u32arr asegs ?m0 A ?l, MU : munch ?W ?m0 ?mx, WM : wmono asegs ?m0 ?mx |- evtA _ _ _ _ (MS _ _ _ _ _ ?mx _) =>
        let D := fresh "WD" in
        assert (D : disjoint_from W A (4 * Z.of_nat (length l)));
        [ first [ solve_disjoint
                | match goal with E : length l = _ |- _ => rewrite E; solve_disjoint end
                | match goal with |- ?g => idtac "WD-LEFT" g end; fail ] | ];
        let UN := fresh "WN" in
        pose proof (u32arr_transport asegs _ m0 mx A l UA MU WM D) as UN; clear UA D; rename UN into H
    end.

  Lemma kob_head : forall (P : Z), 6 <= P <= 8 -> 2 * P <= Z.of_nat (length xs) ->
    forall (h1 : HST asegs R HIA) (FB sp2 : Z) (m1 : mem) (jrp : list byte) (w0 w1 w2 : word)
           (ra1 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 v4 v6 t3 t4 t5 t6 : word),
    HM asegs R HIA h1 LB ((FB, 256) :: LF) m1 -> kob_hrel h1 -> kob_fbok FB -> kob_sp2ok sp2 ->
    mem_inv asegs m1 ->
    presW asegs R HIA h LB LF (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] m m1 ->
    u32arr asegs m1 X xs ->
    rw_cells asegs m1 (Z.shiftr FB 3 + al_sb AL) (kob_meta 248) ->
    rw_cells asegs m1 FB [C8 w0; C8 w1; C8 w2] ->
    u8arr asegs m1 (FB + 32) (repeat (Z_to_bv 8 0) (Z.to_nat 32)) -> aobj asegs AL CS m1 (FB + 32) 32 ->
    rw_cells asegs m1 (FB + 96) [CB 40 jrp] -> length jrp = 40%nat ->
    stk asegs m1 lo sp2 -> stk asegs m1 sp2 (bv_unsigned sp + -256) ->
    rw_cells asegs m1 (bv_unsigned sp + -256) [C8 (Z_to_bv 64 0)] ->
    stk asegs m1 (bv_unsigned sp + -248) (sp2 + 32) -> rw_cells asegs m1 (sp2 + 32) [C8 (Z_to_bv 64 FB)] ->
    stk asegs m1 (sp2 + 40) (sp2 + 64) -> rw_cells asegs m1 (sp2 + 64) [C8 (Z_to_bv 64 (al_sb AL))] ->
    stk asegs m1 (sp2 + 72) (sp2 + 96) -> rw_cells asegs m1 (sp2 + 96) [C8 (Z_to_bv 64 RP); C8 (Z_to_bv 64 X)] ->
    stk asegs m1 (sp2 + 112) (sp2 + 120) -> rw_cells asegs m1 (sp2 + 120) [C8 (Z_to_bv 64 0)] ->
    stk asegs m1 (sp2 + 128) (sp2 + 144) -> rw_cells asegs m1 (sp2 + 144) [C8 (Z_to_bv 64 FB)] ->
    stk asegs m1 (sp2 + 152) (bv_unsigned sp + -104) -> rw_cells asegs m1 (bv_unsigned sp + -104) KSAVES ->
    evtA asegs AL CS (Q P)
      (MS (mkR ra1 (Z_to_bv 64 sp2) gp tp t0 t1 t2 sp (Z_to_bv 64 sp2) a0 a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 (FB + 32)) (Z_to_bv 64 P) v4 (Z_to_bv 64 0) v6 (Z_to_bv 64 P)
               (Z_to_bv 64 FB) (Z_to_bv 64 (FB + 96)) (Z_to_bv 64 (32 * P)) (Z_to_bv 64 (Z.shiftr FB 3 + al_sb AL)) t3 t4 t5 t6)
          F (Z_to_bv 64 0xd7304) fc None m1 (seg_rom asegs)).
  Proof.
    intros P PR XLEN. intros until t6.
    intros HH1 HREL FBOK SP2OK MI PRES XA FSH FHD MPB OM RPB LJR ST1 ST2 C256 ST3 C32 ST4 C64 ST5 C96 ST6 C120 ST7 C144 ST8 CSV.
    rt_facts.
    pose proof HREL as (Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI).
    pose proof FBOK as (FRSH & F64 & F8 & FB0 & FBLO & CFB & INF & IND & APLF & APS & FCE & FDAT & SBND & SAP & XFB & XM).
    pose proof SP2OK as (SP2M & SP2).
    assert (INF0 : In (FB, 256) ((FB, 256) :: LF)) by (left; reflexivity).
    assert (SP2R : 0 <= sp2 < 2^64) by (clear - SP2 SPR SLO LOS ALO ACV NEEDR NER; lia).
    destruct (x_facts _ _ _ _ HH1 XIN) as [X0 XCE].
    pose proof (hm_top asegs R HIA h1 LB ((FB, 256) :: LF) m1 HH1) as HTOP. rewrite Ehtop, Estk in HTOP.
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| qlia| qlia]).
    pose proof (hm_wlow asegs R HIA h1 LB ((FB, 256) :: LF) m1 HH1) as WL.
    pose proof (kh_wlow LB LF (FB, 256) WL) as WL0.
    destruct IMG' as (EGOT & ELO & EHI).
    pose proof (art_stk_high asegs R HIA) as STKH.
    pose proof (alloc_ceiling_top47 (L := arl_L R)) as AC47.
    assert (XUP : X + 4 * Z.of_nat (length xs) + 8 <= 2^47) by (clear - XCE XBL AC47; lia).
    assert (XUP1 : X <= 2^47) by (clear - XUP; lia).
    pose proof (kh_stk3 _ _ _ _ _ _ ST2 C256 ST3 ltac:(simpl_sizes; lia) ltac:(lia) ltac:(lia)) as SA. clear ST2 C256 ST3.
    pose proof (kh_stk2 _ _ _ (sp2 + 72) _ ST4 C64 ltac:(simpl_sizes; lia) ltac:(lia)) as SB. clear ST4 C64.
    pose proof (kh_stk3 _ _ _ _ _ _ ST7 C144 ST8 ltac:(simpl_sizes; lia) ltac:(lia) ltac:(lia)) as SC. clear ST7 C144 ST8.
    unfold kob_meta in FSH; cbn [repeat app] in FSH.
    apply (rw_cells_of_u8arr asegs) in MPB. rewrite repeat_length in MPB. change (Z.to_nat 32) with 32%nat in MPB.
    pose (lxi := lxA_img (arl_AL R) IMG).
    assert (A4P : (X + 4 * P) mod 4 = 0) by (rewrite (Z.mul_comm 4 P), Z.mod_add by lia; exact XAL).
    assert (A32 : (32 * P) mod 32 = 0) by (rewrite Z.mul_comm; apply Z.mod_mul; lia).
    all: lx_mkR; lx_pre; lxe_pose; lx_run_tac (PLAN [A_ASAN_MEMSET_KB; 0xd7770] [] 200%N); lx_tree.
    all: carryX.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m1; rn_frame FB.
    all: rewrite <- Ehcs.
    all: frame_aobj FSH (FB + 96) 5%nat as OA.
    all: apply (u8arr_of_rw_cells asegs) in RPB.
    all: pose proof (artA_amemset asegs R HIA A_ASAN_MEMSET_KB) as SPC.
    all: callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := FB + 96) (v := 0) (n := 40) (lo := lo) (ds := jrp);
      rewrite ?(unsigned_lit sp2) by exact SP2R; amem_ob).
    all: clear SPC; rw_hcs.
    all: kh_tocb (FB + 96) ZPB.
    all: lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m2 end.
    all: lx_mkR; lx_pre; lxe_pose; lx_run_tac (PLAN [A_ASAN_MEMCPY_KB; 0xd7770] [] 200%N); lx_tree.
    all: lxu_chk_leaves 0xd7770.
    all: carryX.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m2; rn_frame FB.
    all: lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m3 end.
    all: frame_aobj FSH (FB + 32) 4%nat as OM.
    all: try replace (4 * P + X) with (X + 4 * P) by lia.
    all: lazymatch goal with |- evtA _ _ _ (Q ?p) _ =>
      destruct (u32arr_mid asegs m3 X xs (Z.to_nat p) (Z.to_nat p) ltac:(cbn; lia) XA) as [XS LXS];
      rewrite Z2Nat.id in XS by lia;
      pose proof (u8arr_of_rw_cells asegs _ _ _ _ MPB) as MPU;
      pose proof (u8arr_zero_prefix asegs m3 (FB + 32) 32%nat (Z.to_nat (4 * p)) ltac:(cbn; lia) MPU) as DSTU;
      assert (OMD : aobj asegs AL CS m3 (FB + 32) (4 * p)) by (eapply aobj_sub; [exact OM | lia | lia]);
      assert (OX : aobj asegs AL (hcs asegs R HIA h1) m3 (X + 4 * p) (4 * p))
        by (eapply aobj_sub; [eapply hm_aobj_block; [eassumption | exact XIN] | lia | lia]);
      assert (DSJ : 4 * p = 0 \/ FB + 32 + 4 * p <= X + 4 * p \/ X + 4 * p + 4 * p <= FB + 32)
        by (clear - XFB XBL XLEN; lia);
      assert (LSS : Z.of_nat (length (u32s (firstn (Z.to_nat p) (skipn (Z.to_nat p) xs)))) = 4 * p)
        by (rewrite u32s_length, LXS; lia);
      assert (LDS : Z.of_nat (length (repeat (Z_to_bv 8 0) (Z.to_nat (4 * p)))) = 4 * p) by (rewrite repeat_length; lia);
      pose proof (proj1 (u8arr_of_u32arr _ _ _ _ XS)) as XSB;
      pose proof (artA_amemcpy asegs R HIA A_ASAN_MEMCPY_KB) as SPC;
      rewrite <- Ehcs;
      callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := FB + 32) (SRC := X + 4 * p) (n := 4 * p)
                       (lo := lo) (ds := repeat (Z_to_bv 8 0) (Z.to_nat (4 * p))) (ss := u32s (firstn (Z.to_nat p) (skipn (Z.to_nat p) xs)));
        rewrite ?(unsigned_lit sp2) by exact SP2R; amem_ob)
    end.
    all: clear SPC; rw_hcs.
    all: clear LDS LSS.
    all: kh_tow (FB + 32) A1.
    all: lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m4 end.
    all: lx_mkR; lx_pre; lxe_pose; lx_run_tac (PLAN [0xd74c8; 0xd7770] [] 200%N); lx_tree.
    all: carryX.
    all: try kh_carryW (FB + 32) A1W.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m4; rn_frame FB.
    all: kh_rfr sp2.
    all: kh_a0s (FB + 96).
    all: replace (Z_to_bv 64 (al_sb AL + Z.shiftr FB 3)) with (Z_to_bv 64 (Z.shiftr FB 3 + al_sb AL)) by (f_equal; lia).
    all: try replace (4 * P + X) with (X + 4 * P) in * by lia.
    all: try replace (2 + P) with (P + 2) in * by lia.
    all: try replace (P * 4) with (4 * P) in * by lia.
    all: lazymatch goal with |- evtA _ _ _ (Q ?p) (MS _ _ _ _ _ ?mx _) =>
      assert (RFR : kob_rfr p FB sp2 mx)
        by (unfold kob_rfr; refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _)))))); eassumption);
      eapply (kob_pass1 p)
    end.
    all: first [ eassumption | reflexivity | unfold kob_meta; cbn [repeat app]; eassumption | lia | apply repeat_length ].
  Qed.

  Lemma kob_pro : forall (P : Z), 6 <= P <= 8 -> 2 * P <= Z.of_nat (length xs) ->
    forall (t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
    HM asegs R HIA h LB LF m -> u32arr asegs m X xs -> stk asegs m lo (bv_unsigned sp) -> mem_inv asegs m ->
    evtA asegs AL CS (Q P)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 X) (Z_to_bv 64 RP) (Z_to_bv 64 (32 * P)) a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 A_ECP_KOBLITZ) fc None m (seg_rom asegs)).
  Proof.
    intros P PR XLEN. intros until t6. intros HH XA ST MI. unfold A_ECP_KOBLITZ. rt_facts.
    pose proof (hm_top asegs R HIA h LB LF _ HH) as HTOP.
    destruct (x_facts _ _ _ _ HH XIN) as [X0 XCE].
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| qlia| qlia]).
    pose proof (hm_wlow asegs R HIA h LB LF m HH) as WL.
    pose proof (presW_init asegs R HIA h LB LF m (bv_unsigned sp) (arl_stklo R) [(X, X + 4 * (2 * P))] HH ltac:(clear - LOS; lia)) as PRES.
    destruct IMG' as (EGOT & ELO & EHI).
    pose proof (hm_abase asegs R HIA h LB LF m HH) as AB.
    pose proof (abase_got _ _ _ AB) as GOT; pose proof (abase_gsb _ _ _ AB) as GSB.
    destruct (hm_auar asegs R HIA h LB LF m HH) as [UGOT UFLAG].
    pose proof (hm_flag_img asegs R HIA h LB LF m HH) as FLIMG.
    rewrite EGOT in GOT. rewrite UARG in UGOT.
    pose (lxi := lxA_img (arl_AL R) IMG).
    lx_mkR. lx_pre. lxe_pose. lx_run_tac (PLAN [A_SMALLOC_2_KB; 0xd7770] [] 80%N). lx_tree.
    all: carryX.
    all: lxr_leaf; lxe_leaf_gc.
    clear GOT GSB UGOT UFLAG AB FLIMG.
    lx_align32 sp2.
    match goal with Hm : sp2 mod 32 = 0 |- _ => rename Hm into SP2M end.
    assert (SP2 : bv_unsigned sp - 272 <= sp2 <= bv_unsigned sp - 256)
      by (match goal with H1 : 0 <= sp2 + _, H2 : 0 <= - sp2 + _ |- _ => clear - H1 H2 SP2M SPA SPR end; Z.div_mod_to_equations; lia).
    assert (SP2R : 0 <= sp2 < 2^64) by (clear - SP2 SPR SLO LOS ALO ACV NEEDR NER; lia).
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m1 end.
    match goal with H : stk _ m1 lo (bv_unsigned sp + -256) |- _ => rename H into ST0 end.
    destruct (stk_split asegs m1 lo sp2 (bv_unsigned sp + -256) ST0 ltac:(clear - SP2 SLO NS1 NES; lia)) as [ST1 ST2]. clear ST0.
    replace (Z_to_bv 64 0x531fc) with (Z_to_bv 64 (arl_smalloc R 2)) by (rewrite SM2; reflexivity).
    lazymatch goal with HHc : HM _ _ _ h LB LF m1 |- _ =>
    callrt sp2 (eapply (art_smalloc asegs R HIA 2) with (lo := lo) (sz := 192); rewrite ?(unsigned_lit sp2) by exact SP2R;
                first [ exact HHc | reflexivity | exact TPV | exact LOS | exact ST1
                | clear - LFB; lia
                | clear - SLO SP2 TOP NS1 NES; lia
                | clear; lia
                | assumption | match goal with |- ?g => idtac "SMPRE-LEFT:" g end ])
    end.
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "SMALLOC-LEFT:" g end.
    clear ST1.
    lazymatch goal with H : presA _ _ _ _ _ _ _ _ m1 ?m2 |- _ => rename H into HP1; rename m2 into m2' end.
    match goal with H : HM _ _ _ h LB LF m1 |- _ => clear H end.
    pose proof (x_presA _ _ _ _ _ _ _ _ xs HP1 XA XIN XBL ltac:(cbn; exact I)) as XA2. clear XA. rename XA2 into XA.
    presA_transport HP1. clear HP1.
    lazymatch goal with H : exists h' : HST _ _ _, _ |- _ =>
      destruct H as (h1 & Ehcs & Ehtop & Estk & Eflag & Evol & Efr & HKI & SMC) end.
    destruct SMC as (FB & junkf & Ea0 & F64 & FRSH & HH1 & FRM & FSH). lazymatch type of Ea0 with ?x = _ => subst x end.
    cbn [Z.mul Z.pow Z.pow_pos Pos.iter Pos.mul Z.to_nat Pos.to_nat Pos.iter_op Nat.add Nat.mul] in FRSH, HH1, FRM, FSH.
    change (64 * 2 ^ 2) with 256 in *. change (8 * 2 ^ 2) with 32 in FSH. change (Z.to_nat 256) with 256%nat in FRM. change (Z.to_nat 32) with 32%nat in FSH.
    lazymatch goal with |- _ (MS _ _ _ _ _ ?mc _) => rename mc into m3 end.
    destruct (frame_factsA R HIA CS h1 LB LF m3 FB 256 lo HH1 Ehcs FRSH F64 ltac:(clear; lia) ltac:(reflexivity) LOS)
      as (CFB & INF & INH & IND & AP & (F0 & F1 & F2 & F3) & F8 & FBLO & SBND & APS). change (256 / 8) with 32 in SBND, APS. change (256 - 40) with 216 in IND.
    pose proof (art_stk_high asegs R HIA) as STKH.
    assert (XFB : FB + 256 <= X \/ X + XB <= FB).
    { destruct FRSH as (_ & _ & _ & G3). pose proof (G3 X XB ltac:(apply in_app_iff; left; exact XIN)) as K. clear - K. lia. }
    assert (XM : X + XB <= Z.shiftr FB 3 + al_sb AL \/ Z.shiftr FB 3 + al_sb AL + 32 <= X).
    { assert (CX : crange CS X XB) by (rewrite <- Ehcs; eapply aobj_crange; eapply hm_aobj_block; [exact HH1| exact XIN]).
      eapply (apart_client_shadow AL CS X XB FB (Z.shiftr FB 3 + al_sb AL) 32 CSOK CX);
        [change (8 * 32) with 256; exact CFB| shadow_addr_eq | clear - XBL XLEN PR; lia | clear; lia]. }
    apply (rw_cells_split_CB asegs m3 FB [] 256 junkf [] [8; 8; 8; 8; 32; 32; 40; 120]%nat) in FRM; [| reflexivity].
    cbn [mk_CB_cells app] in FRM.
    chunk_split FRM 3%nat FHD FRM1. chunk_split FRM1 1%nat FLNK FRM2. chunk_split FRM2 1%nat MPB FRM3. chunk_split FRM3 1%nat RZC FRM4. chunk_split FRM4 1%nat RPB FREST.
    lazymatch type of MPB with rw_cells _ _ ?a _ => replace a with (FB + 32) in MPB by (clear; lia) end.
    lazymatch type of RPB with rw_cells _ _ ?a _ => replace a with (FB + 96) in RPB by (clear; lia) end.
    clear FLNK FREST RZC.
    lazymatch type of MPB with rw_cells _ _ _ [CB _ ?j] => set (jmp := j) in MPB; clearbody jmp end.
    lazymatch type of RPB with rw_cells _ _ _ [CB _ ?j] => set (jrp := j) in RPB; clearbody jrp end.
    repeat match type of FHD with context [CB 8 ?j] =>
      lazymatch j with context [junkf] => let v := fresh "hj" in set (v := j) in FHD; clearbody v end end.
    cb8_to_c8 FHD (@nil cell).
    lazymatch type of FHD with rw_cells _ _ _ (?c0 :: _) => cb8_to_c8 FHD [c0] end.
    lazymatch type of FHD with rw_cells _ _ _ (?c0 :: ?c1 :: _) => cb8_to_c8 FHD [c0; c1] end.
    clear junkf.
    cbn [zcells] in FSH.
    pose proof (alloc_ceiling_top47 (L := arl_L R)) as AC47.
    assert (A32 : (32 * P) mod 32 = 0) by (rewrite Z.mul_comm; apply Z.mod_mul; lia).
    all: lx_mkR; lx_pre; lxe_pose; lx_run_tac (PLAN [A_ASAN_MEMSET_KB; 0xd7770] [] 200%N); lx_tree.
    all: carryX.
    all: lxr_leaf; lxe_leaf_gc.
    all: dropmem m1; dropmem m3; rn_frame FB.
    all: rewrite <- Ehcs.
    all: pose proof (cells_at_wf _ _ _ _ (proj1 MPB)) as WF; cbn [cells_wf cell_wf] in WF; destruct WF as [LJM _].
    all: pose proof (cells_at_wf _ _ _ _ (proj1 RPB)) as WF; cbn [cells_wf cell_wf] in WF; destruct WF as [LJR _].
    all: frame_aobj FSH (FB + 32) 4%nat as OM.
    all: apply (u8arr_of_rw_cells asegs) in MPB.
    all: pose proof (artA_amemset asegs R HIA A_ASAN_MEMSET_KB) as SPC.
    all: callxA_sp sp2 (eapply SPC with (h := h1) (LB := LB) (LF := (FB, 256) :: LF) (DST := FB + 32) (v := 0) (n := 32) (lo := lo) (ds := jmp);
      rewrite ?(unsigned_lit sp2) by exact SP2R; amem_ob).
    all: clear SPC; rw_hcs.
    all: try replace (Z.shiftr (32 * P) 5) with P in * by (rewrite Z.shiftr_div_pow2 by lia; Z.div_mod_to_equations; lia).
    all: try replace (Z.land (32 * P) 31) with 0 in * by (change 31 with (2 ^ 5 - 1); rewrite lxu_land_ones by lia; symmetry; exact A32).
    all: lazymatch goal with |- evtA _ _ _ (Q ?p) _ => eapply (kob_head p) end.
    all: first [ eassumption
               | unfold kob_meta; cbn [repeat app]; eassumption
               | unfold kob_fbok, kob_sp2ok, kob_hrel; repeat (first [assumption | split]) ].
  Qed.

End KW.

Lemma A_ecp_koblitz_spec : forall (R : art_layout) (HIA : artA asegs R),
  asan_img_ok (arl_AL R) ->
  arl_uar_got R = A_UAR_GOT_KB ->
  arl_smalloc R 2 = A_SMALLOC_2_KB ->
  0 <= arl_need_smalloc R -> 0 <= arl_need_rt R ->
  arl_amemset R = A_ASAN_MEMSET_KB ->
  arl_amemcpy R = A_ASAN_MEMCPY_KB ->
  mpi_core_mul_stmtA asegs R HIA A_MPI_CORE_MUL ->
  mpi_core_add_stmtA asegs (arl_AL R) A_MPI_CORE_ADD ->
  koblitz_stmtB asegs R HIA A_ECP_KOBLITZ.
Proof.
  intros R HIA IMG UARG SM2 NS1 NEEDR AMS AMC CMUL CADD. unfold koblitz_stmtB.
  intros h LB LF ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m
         X XB RP bits lo xs rs HH LFB BITS XA XLEN XIN XBL XAL RT RPL ST LOS SLO TOP SPA TPV MI RAE E0 E1 E2.
  subst a0 a1 a2.
  assert (PR : 6 <= bits / 32 <= 8) by (destruct BITS as [E|[E|E]]; subst bits; cbn; lia).
  assert (EA : Z_to_bv 64 bits = Z_to_bv 64 (32 * (bits / 32))) by (f_equal; destruct BITS as [E|[E|E]]; subst bits; reflexivity).
  assert (EXL : koblitz_xl bits = 2 * (bits / 32)) by (unfold koblitz_xl; destruct BITS as [E|[E|E]]; subst bits; reflexivity).
  rewrite EXL in XLEN |- *. rewrite EA.
  eapply kob_pro; eassumption.
Qed.
